hild {...dropzoneProps}>\n    75\t        <div data-agent-ui-owned=\"\"\n    76\t          data-slot=\"aui_composer-shell\"\n    77\t          className=\"border-border/60 data-[dragging=true]:border-ring focus-within:border-border dark:border-muted-foreground/15 dark:focus-within:border-muted-foreground/30 flex w-full cursor-text flex-col gap-2 rounded-(--composer-radius) border bg-(--composer-bg) p-(--composer-padding) transition-[border-color] data-[draggin…","role":"tool"}

